	private void assertParity(String query, BindingSet bindings, String baseURI) {
		String rewritten = SPARQLQueries.withQueryBindings(query, bindings);
		try (RepositoryConnection connection = repository.getConnection()) {
			var original = connection.prepareTupleQuery(QueryLanguage.SPARQL, query, baseURI);
			for (var binding : bindings) {
				original.setBinding(binding.getName(), binding.getValue());
			}
			try (var expected = original.evaluate();
					var actual = connection.prepareTupleQuery(QueryLanguage.SPARQL, rewritten, baseURI).evaluate()) {
				assertEquals(new HashSet<>(expected.getBindingNames()), new HashSet<>(actual.getBindingNames()),
						rewritten);
				Map<Map<String, Value>, Integer> expectedBag = new HashMap<>();
				Map<Map<String, Value>, Integer> actualBag = new HashMap<>();
				expected.forEachRemaining(row -> add(expectedBag, row));
				actual.forEachRemaining(row -> add(actualBag, row));
				assertEquals(expectedBag, actualBag, rewritten);
			}
		}
	}

	private static void add(Map<Map<String, Value>, Integer> bag, BindingSet row) {
		Map<String, Value> values = new TreeMap<>();
		for (var binding : row) {
			values.put(binding.getName(), binding.getValue());
		}
		bag.merge(values, 1, Integer::sum);
	}

	private static MapBindingSet binding(String name, Value value) {
		MapBindingSet result = new MapBindingSet();
		result.addBinding(name, value);
		return result;
	}
